import pandas as pd,numpy as np
from sklearn.linear_model import LinearRegression
c=pd.read_json('data/furniture.json');d=pd.read_csv('data/sales_san_francisco.csv').merge(c,left_on='product_id',right_on='furniture_id');d['lp']=np.log(d.furniture_price);d['lq']=np.log(d.quantity)
for slope in [None,-0.6,-0.77,-1.0]:
 errors=[]
 for cat,g in d.groupby('furniture_type'):
  train=d[d.furniture_type!=cat]
  if slope is None:
   m=LinearRegression().fit(train[['lp']],train.lq);pred=np.exp(m.predict(g[['lp']]))
  else:
   offsets=(train.lq-slope*train.lp).groupby(train.furniture_type).mean();pred=np.exp(offsets.mean()+slope*g.lp)
  errors.extend((pred-g.quantity).tolist())
 print('unseen-category method',slope,'MAE',round(np.mean(np.abs(errors)),2),'RMSE',round(np.sqrt(np.mean(np.array(errors)**2)),2))
for name in ['Back Bay King Bed Frame','Back Bay Bookcase','Back Bay Brass End Table','Back Bay Accent Chair','Back Bay Desk Chair']:
 r=c[c.furniture_name==name].iloc[0];g=d[d.furniture_type==r.furniture_type];price=r.furniture_price
 if len(g):
  baseline=float(np.exp(np.mean(g.lq+0.77*g.lp)-0.77*np.log(price)));obs=d[d.furniture_name==name].quantity.tolist();print(name,'category_price_baseline',round(baseline,1),'observed',obs)
 else:
  for slope in [-0.6,-0.77]:
   offsets=(d.lq-slope*d.lp).groupby(d.furniture_type).mean();print(name,'unseen_category',slope,round(float(np.exp(offsets.mean()+slope*np.log(price))),1))
